import { useId, useState, type ReactNode } from "react";
import { Button } from "./button";
import { IconButton } from "./icon-button";
import { ChevronLeftIcon, ChevronRightIcon, MenuIcon } from "./monotone-icons";
import {
    Drawer, DrawerClose, DrawerContent, DrawerDescription,
    DrawerTitle, DrawerTrigger,
} from "./drawer";
import { SideNav, SideNavLink, type SideNavLinkProps } from "./navigation";
import { cn } from "./utils";
import { SidebarResizeHandle, useSidebarResize } from "./sidebar/resize";

type SidebarItem = {
    id: string;
    label: string;
    href: string;
    icon?: ReactNode;
    current?: boolean;
};

type SidebarSection = {
    id: string;
    label: string;
    items: readonly SidebarItem[];
};

type SidebarProps = ({
    items: readonly SidebarItem[];
    sections?: never;
} | {
    items?: never;
    sections: readonly SidebarSection[];
}) & {
    label: string;
    side?: "left" | "right";
    linkVariant?: SideNavLinkProps["variant"];
    collapsed?: boolean;
    defaultCollapsed?: boolean;
    resizable?: boolean;
    resizeStorageKey?: string;
    onCollapsedChange?: (collapsed: boolean) => void;
    mobileOpen?: boolean;
    defaultMobileOpen?: boolean;
    onMobileOpenChange?: (open: boolean) => void;
    onNavigate?: (id: string) => void;
    className?: string;
};

function Sidebar({
    label,
    items,
    sections,
    side = "left",
    linkVariant = "rail",
    collapsed,
    defaultCollapsed = false,
    resizable = true,
    resizeStorageKey,
    onCollapsedChange,
    mobileOpen,
    defaultMobileOpen = false,
    onMobileOpenChange,
    onNavigate,
    className,
}: SidebarProps) {
    if (typeof label !== "string" || !label.trim()) {
        throw new Error("Sidebar requires a label and named links.");
    }
    if (linkVariant !== "rail" && linkVariant !== "filled") {
        throw new RangeError("Sidebar link variant is not supported.");
    }
    if ((items === undefined) === (sections === undefined) ||
        (items !== undefined && !Array.isArray(items)) ||
        (sections !== undefined && !Array.isArray(sections))) {
        throw new Error("Sidebar requires items or sections, not both.");
    }
    if (sections?.some((section) =>
        !section || typeof section.id !== "string" || !section.id.trim() ||
        typeof section.label !== "string" || !section.label.trim() ||
        !Array.isArray(section.items) || section.items.length === 0
    ) || (sections && new Set(sections.map((section) => section.id)).size !==
        sections.length)) {
        throw new Error("Sidebar sections need unique IDs, labels, and links.");
    }
    const links = items ?? sections!.flatMap((section) => section.items);
    if (links.some((item) =>
        !item || typeof item.id !== "string" || !item.id.trim() ||
        typeof item.label !== "string" || !item.label.trim() ||
        typeof item.href !== "string" || !item.href.trim()
    )) {
        throw new Error("Sidebar requires a label and named links.");
    }
    if (new Set(links.map((item) => item.id)).size !== links.length) {
        throw new Error("Sidebar item ids must be unique.");
    }

    const [internalCollapsed, setInternalCollapsed] = useState(defaultCollapsed);
    const [internalMobileOpen, setInternalMobileOpen] = useState(
        defaultMobileOpen,
    );
    const navId = useId();
    const isCollapsed = collapsed ?? internalCollapsed;
    const isMobileOpen = mobileOpen ?? internalMobileOpen;
    const resize = useSidebarResize({
        defaultWidth: 224, minWidth: 160, maxWidth: 420, contentWidth: 320,
        side, enabled: resizable && !isCollapsed, storageKey: resizeStorageKey,
    });

    function changeCollapsed(next: boolean) {
        if (collapsed === undefined) setInternalCollapsed(next);
        onCollapsedChange?.(next);
    }

    function changeMobileOpen(next: boolean) {
        if (mobileOpen === undefined) setInternalMobileOpen(next);
        onMobileOpenChange?.(next);
    }

    function link(item: SidebarItem, compact: boolean, mobile = false) {
        return (
            <SideNavLink
                key={item.id}
                variant={linkVariant}
                href={item.href}
                aria-current={item.current ? "page" : undefined}
                title={item.label}
                className={cn(
                    "flex min-w-0 items-center gap-3 whitespace-nowrap",
                    compact && "justify-center px-2",
                )}
                onClick={() => {
                    onNavigate?.(item.id);
                    if (mobile) changeMobileOpen(false);
                }}
            >
                <span aria-hidden="true" className={
                    "grid size-5 shrink-0 place-items-center text-xs font-semibold"
                }>
                    {item.icon ?? Array.from(item.label)[0]}
                </span>
                <span className={compact ? "sr-only" : "min-w-0 flex-1 truncate"}>
                    {item.label}
                </span>
            </SideNavLink>
        );
    }

    function navigation(compact: boolean, mobile = false) {
        if (!sections) return links.map((item) => link(item, compact, mobile));
        return sections.map((section, index) => {
            const headingId = `${navId}-${mobile ? "mobile" : "desktop"}-${index}`;
            return (
                <div key={section.id} role="group" aria-labelledby={headingId}
                    className={cn("grid gap-1", index > 0 && "mt-2 border-t border-border pt-2")}>
                    <h3 id={headingId} className={cn(
                        "m-0 px-3 pb-1 pt-2 text-xs font-semibold text-muted",
                        compact && "sr-only",
                    )}>
                        {section.label}
                    </h3>
                    {section.items.map((item) => link(item, compact, mobile))}
                </div>
            );
        });
    }

    return (
        <>
            <aside ref={resize.panelRef}
                style={resizable && !isCollapsed ? resize.style : undefined}
                className={cn(
                "relative hidden min-h-0 shrink-0 flex-col border-border " +
                "bg-surface-subtle text-foreground " +
                "transition-[width] duration-[var(--motion-fast)] " +
                "motion-reduce:transition-none @3xl:flex",
                isCollapsed ? "w-16" : resizable ? "w-[var(--sidebar-width)]" : "w-56",
                resize.handle.dragging && "transition-none",
                side === "left" ? "border-r" : "border-l",
                side === "right" && "order-last",
                className,
            )} data-ui="sidebar">
                <div data-slot="surface-header" className={cn(
                    "flex min-h-14 items-center gap-2 border-b border-border p-2",
                    isCollapsed ? "justify-center" : "justify-between",
                )}>
                    {!isCollapsed && (
                        <strong data-slot="surface-title"
                            className="min-w-0 truncate px-2 text-sm">
                            {label}
                        </strong>
                    )}
                    <IconButton
                        variant="ghost"
                        label={isCollapsed ? "탐색 펼치기" : "탐색 접기"}
                        icon={side === "left"
                            ? isCollapsed ? <ChevronRightIcon /> : <ChevronLeftIcon />
                            : isCollapsed ? <ChevronLeftIcon /> : <ChevronRightIcon />}
                        aria-expanded={!isCollapsed}
                        aria-controls={navId}
                        onClick={() => changeCollapsed(!isCollapsed)}
                    />
                </div>
                <SideNav id={navId} aria-label={label}
                    className="min-h-0 flex-1 content-start overflow-y-auto p-2">
                    {navigation(isCollapsed)}
                </SideNav>
                {resizable && !isCollapsed && (
                    <SidebarResizeHandle {...resize.handle} label={`${label} 너비`} controls={navId} />
                )}
            </aside>
            <div className="p-2 @3xl:hidden">
                <Drawer open={isMobileOpen} onOpenChange={changeMobileOpen}>
                    <DrawerTrigger asChild>
                        <Button variant="outline" aria-label={`${label} 열기`}>
                            <MenuIcon /> 탐색
                        </Button>
                    </DrawerTrigger>
                    <DrawerContent side={side}
                        className="flex w-[min(20rem,calc(100vw-2rem))] flex-col p-0">
                        <div data-slot="surface-header" className={
                            "flex items-center justify-between gap-2 " +
                            "border-b border-border p-[var(--space-3)]"
                        }>
                            <DrawerTitle className="text-sm font-semibold">
                                {label}
                            </DrawerTitle>
                            <DrawerDescription className="sr-only">
                                페이지 탐색 링크를 선택합니다.
                            </DrawerDescription>
                            <DrawerClose asChild>
                                <Button variant="ghost" aria-label="탐색 닫기">
                                    닫기
                                </Button>
                            </DrawerClose>
                        </div>
                        <SideNav aria-label={label}
                            className="content-start overflow-y-auto p-2">
                            {navigation(false, true)}
                        </SideNav>
                    </DrawerContent>
                </Drawer>
            </div>
        </>
    );
}

export { Sidebar, SidebarResizeHandle, useSidebarResize };
export type { SidebarItem, SidebarSection, SidebarProps };

import { useEffect, useRef, useState, type CSSProperties, type KeyboardEvent, type PointerEvent } from "react";

type SidebarResizeOptions = {
  defaultWidth: number;
  minWidth: number;
  maxWidth: number;
  contentWidth: number | ((available: number) => number);
  side?: "left" | "right";
  enabled?: boolean;
  storageKey?: string;
};

export function useSidebarResize({
  defaultWidth,
  minWidth,
  maxWidth,
  contentWidth,
  side = "left",
  enabled = true,
  storageKey,
}: SidebarResizeOptions) {
  const panelRef = useRef<HTMLElement>(null);
  const [preferred, setPreferred] = useState(defaultWidth);
  const [available, setAvailable] = useState<number>();
  const [dragging, setDragging] = useState(false);
  const drag = useRef<{
    pointerId: number;
    start: number;
    x: number;
    preferred: number;
    width: number;
  } | null>(null);

  useEffect(() => {
    if (!storageKey) return;
    try {
      const saved = localStorage.getItem(storageKey);
      const parsed = saved === null ? defaultWidth : Number(saved);
      setPreferred(Number.isFinite(parsed) ? Math.max(minWidth, Math.min(maxWidth, parsed)) : defaultWidth);
    } catch {
      setPreferred(defaultWidth);
    }
  }, [storageKey, defaultWidth, minWidth, maxWidth]);

  useEffect(() => {
    if (!enabled) return;
    const parent = panelRef.current?.parentElement;
    if (!parent) return;
    const measure = () => setAvailable(parent.clientWidth);
    measure();
    if (typeof ResizeObserver !== "function") return;
    const observer = new ResizeObserver(measure);
    observer.observe(parent);
    return () => observer.disconnect();
  }, [enabled]);

  const maximum = available === undefined || available === 0 ? maxWidth : Math.max(
    minWidth,
    Math.min(maxWidth, available - (typeof contentWidth === "function" ? contentWidth(available) : contentWidth)),
  );
  const clamp = (width: number) => Math.round(Math.max(minWidth, Math.min(maximum, width)));
  const width = clamp(preferred);
  const direction = side === "left" ? 1 : -1;

  function save(value: number) {
    setPreferred(value);
    if (!storageKey) return;
    try {
      localStorage.setItem(storageKey, String(value));
    } catch {
      // Resizing is available when browser storage is disabled.
    }
  }

  function finish(event: PointerEvent<HTMLDivElement>, commit: boolean) {
    const current = drag.current;
    if (current?.pointerId !== event.pointerId) return;
    drag.current = null;
    setDragging(false);
    if (commit && current.width !== current.start) save(clamp(current.width));
    else setPreferred(current.preferred);
  }

  return {
    panelRef,
    style: { "--sidebar-width": `${width}px` } as CSSProperties,
    handle: {
      side,
      width,
      minimum: minWidth,
      maximum,
      dragging,
      onPointerDown(event: PointerEvent<HTMLDivElement>) {
        if (!enabled || event.button !== 0 || drag.current) return;
        event.preventDefault();
        event.currentTarget.focus({ preventScroll: true });
        event.currentTarget.setPointerCapture(event.pointerId);
        drag.current = { pointerId: event.pointerId, x: event.clientX, start: width, width, preferred };
        setDragging(true);
      },
      onPointerMove(event: PointerEvent<HTMLDivElement>) {
        const current = drag.current;
        if (current?.pointerId !== event.pointerId) return;
        current.width = clamp(current.start + (event.clientX - current.x) * direction);
        setPreferred(current.width);
      },
      onPointerUp: (event: PointerEvent<HTMLDivElement>) => finish(event, true),
      onPointerCancel: (event: PointerEvent<HTMLDivElement>) => finish(event, false),
      onLostPointerCapture: (event: PointerEvent<HTMLDivElement>) => finish(event, false),
      onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
        const step = event.shiftKey ? 32 : 16;
        const keys = { ArrowLeft: width - step * direction, ArrowRight: width + step * direction, Home: minWidth, End: maximum };
        if (!Object.hasOwn(keys, event.key)) return;
        event.preventDefault();
        if (enabled) save(clamp(keys[event.key as keyof typeof keys]));
      },
    },
  };
}

type SidebarResizeHandleProps = ReturnType<typeof useSidebarResize>["handle"] & {
  label: string;
  controls: string;
  className?: string;
};

export function SidebarResizeHandle({
  side, label, controls, width, minimum, maximum, dragging, className, ...events
}: SidebarResizeHandleProps) {
  return (
    <div
      role="separator"
      tabIndex={0}
      aria-label={label}
      aria-controls={controls}
      aria-orientation="vertical"
      aria-valuemin={minimum}
      aria-valuemax={maximum}
      aria-valuenow={width}
      aria-valuetext={`${width}px`}
      data-slot="sidebar-resize-handle"
      data-dragging={dragging || undefined}
      className={[
        "absolute inset-y-0 z-10 w-3 touch-none cursor-col-resize select-none",
        "before:absolute before:inset-y-0 before:w-px before:bg-border before:content-['']",
        "hover:before:w-0.5 hover:before:bg-accent data-[dragging=true]:before:w-0.5 data-[dragging=true]:before:bg-accent",
        "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-focus",
        side === "left" ? "right-0 before:right-0" : "left-0 before:left-0",
        className,
      ].filter(Boolean).join(" ")}
      {...events}
    />
  );
}
